                            onClick={() => setLightboxImage({ base64: displayImage, mimeType: 'image/png' })}
                        />
                         {!editedImage && (
                            <div className="absolute top-1 right-1 bg-slate-900/80 text-sky-400 text-xs px-2 py-0.5 rounded-full backdrop-blur-sm">
                                Live Preview (1K)
