      )}
      {notification && !error && (
        <div className="fixed bottom-6 left-1/2 -translate-x-1/2 bg-slate-700 text-slate-200 px-6 py-3 rounded-full shadow-lg animate-[meebot-fadeIn_420ms_ease-out_both] z-[60]">
