  lastActivity: number;
  recoveryConfig?: RecoveryConfig;
}

export interface TransactionRequest {
  to: `0x${string}`;
  value: string;
  data?: `0x${string}`;
  gasLimit?: string;
}

export interface UserOperation {
  sender: `0x${string}`;
  nonce: bigint;
  initCode: `0x${string}`;
  callData: `0x${string}`;
  accountGasLimits: `0x${string}`;
