// ===== MISSION TRACKER =====
export class MissionTracker {
  private contract: ethers.Contract;
  private provider: ethers.Provider;
  private signer: ethers.Signer;

  constructor(provider: ethers.Provider, signer: ethers.Signer) {
    this.provider = provider;
    this.signer = signer;
    this.contract = new ethers.Contract(
      CONFIG.CONTRACTS.MISSION_TRACKER,
      MISSION_TRACKER_ABI,
      signer
    );
  }

  /**
   * Complete a mission with proof
   */
  async completeMission(
    missionId: string,
    proof: string
  ): Promise<{ success: boolean; txHash: string }> {
    try {
      console.log(`🎯 Completing mission: ${missionId}`);

      const proofBytes = ethers.toBeHex(proof);
      const tx = await this.contract.completeMission(missionId, proofBytes);

      const receipt = await tx.wait();
      console.log(`✅ Mission completed:`, receipt?.hash);

      return {
        success: true,
        txHash: receipt?.hash || '',
      };
    } catch (error) {
      console.error('Mission completion error:', error);
      throw new Error(`Failed to complete mission: ${error}`);
    }
  }

  /**
   * Verify if a user has completed a mission
   */
  async verifyCompletion(userAddress: string, missionId: string): Promise<boolean> {
    try {
      const completed = await this.contract.verifyCompletion(userAddress, missionId);
      return completed;
    } catch (error) {
      console.error('Verification error:', error);
      return false;
    }
  }

  /**
   * Get mission metadata from IPFS
   */
  async getMissionMetadata(missionId: string): Promise<Mission | null> {
    try {
      const ipfsUri = await this.contract.getMissionMetadata(missionId);
      if (!ipfsUri) return null;

      const cid = ipfsUri.replace('ipfs://', '');
      const response = await fetch(`${CONFIG.IPFS_GATEWAY}${cid}`);
      const metadata = await response.json();

      return {
        id: missionId,
        ...metadata,
      };
    } catch (error) {
      console.error('Metadata fetch error:', error);
      return null;
    }
  }

  /**
   * Reward user for mission completion
   */
  async rewardUser(
    userAddress: string,
    missionId: string,
    tokenAmount: string
  ): Promise<string> {
    try {
      console.log(`🎁 Rewarding ${userAddress} for mission ${missionId}`);

      const amount = ethers.parseEther(tokenAmount);
      const tx = await this.contract.rewardUser(userAddress, missionId, amount);

      const receipt = await tx.wait();
      console.log(`✅ Reward distributed:`, receipt?.hash);

      return receipt?.hash || '';
    } catch (error) {
      console.error('Reward distribution error:', error);
      throw new Error(`Failed to reward user: ${error}`);
    }
  }

  /**
   * Create a new mission (for admins)
   */
  async createMission(mission: Mission): Promise<string> {
    try {
      // Upload metadata to IPFS first
      const ipfsUri = await this.uploadMissionMetadata(mission);

      // Create mission on-chain
      // This would be a custom function on the contract
      console.log(`📝 Mission created with metadata at ${ipfsUri}`);

      return ipfsUri;
    } catch (error) {
      console.error('Mission creation error:', error);
      throw new Error(`Failed to create mission: ${error}`);
    }
  }

  private async uploadMissionMetadata(mission: Mission): Promise<string> {
    // Upload to IPFS via Pinata
    const response = await fetch('https://api.pinata.cloud/pinning/pinJSONToIPFS', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${process.env.PINATA_JWT}`,
      },
      body: JSON.stringify(mission),
    });

    const data = await response.json() as { IpfsHash: string };
    return `ipfs://${data.IpfsHash}`;
  }
}

// ===== NFT MANAGER =====
export class NFTManager {
  private contract: ethers.Contract;
  private provider: ethers.Provider;
  private signer: ethers.Signer;

  constructor(provider: ethers.Provider, signer: ethers.Signer) {
    this.provider = provider;
    this.signer = signer;
    this.contract = new ethers.Contract(
      CONFIG.CONTRACTS.NFT_MANAGER,
      NFT_MANAGER_ABI,
      signer
    );
  }

  /**
   * Mint a new NFT
   */
  async mintNFT(to: string, uri: string): Promise<{ tokenId: string; txHash: string }> {
    try {
      console.log(`🖼️ Minting NFT to ${to}`);

      const tx = await this.contract.mintNFT(to, uri);
      const receipt = await tx.wait();

      // Extract tokenId from logs
      const iface = new ethers.Interface(NFT_MANAGER_ABI);
      const logs = receipt?.logs || [];
      let tokenId = '0';

      for (const log of logs) {
        try {
          const parsed = iface.parseLog(log);
          if (parsed?.name === 'Transfer') {
            tokenId = parsed.args[2].toString();
            break;
          }
        } catch (e) {
          // Skip logs that don't match the interface
        }
      }

      console.log(`✅ NFT minted:`, tokenId);

      return {
        tokenId,
        txHash: receipt?.hash || '',
      };
    } catch (error) {
      console.error('NFT mint error:', error);
      throw new Error(`Failed to mint NFT: ${error}`);
    }
  }

  /**
   * Evolve an existing NFT
   */
  async evolveNFT(tokenId: string, newUri: string): Promise<string> {
    try {
      console.log(`🔄 Evolving NFT #${tokenId}`);

      const tx = await this.contract.evolveNFT(tokenId, newUri);
      const receipt = await tx.wait();

      console.log(`✅ NFT evolved:`, receipt?.hash);

      return receipt?.hash || '';
    } catch (error) {
      console.error('NFT evolution error:', error);
      throw new Error(`Failed to evolve NFT: ${error}`);
    }
  }

  /**
   * Get user's NFT balance
   */
  async getBalance(userAddress: string): Promise<number> {
    try {
      const balance = await this.contract.balanceOf(userAddress);
      return Number(balance);
    } catch (error) {
      console.error('Balance check error:', error);
      return 0;
    }
  }

  /**
   * Get NFT metadata from IPFS
   */
  async getNFTMetadata(uri: string): Promise<NFTCard | null> {
    try {
      const cid = uri.replace('ipfs://', '');
      const response = await fetch(`${CONFIG.IPFS_GATEWAY}${cid}`);
      const metadata = await response.json();
      return metadata;
    } catch (error) {
      console.error('NFT metadata fetch error:', error);
      return null;
    }
  }
}

// ===== BADGE SYSTEM =====
export class BadgeSystem {
  private contract: ethers.Contract;
  private provider: ethers.Provider;
  private signer: ethers.Signer;

  constructor(provider: ethers.Provider, signer: ethers.Signer) {
    this.provider = provider;
    this.signer = signer;
    this.contract = new ethers.Contract(
      CONFIG.CONTRACTS.BADGE_SYSTEM,
      BADGE_SYSTEM_ABI,
      signer
    );
  }

  /**
   * Award a badge to a user
   */
  async awardBadge(userAddress: string, badgeId: number): Promise<string> {
    try {
      console.log(`🏅 Awarding badge ${badgeId} to ${userAddress}`);

      const tx = await this.contract.awardBadge(userAddress, badgeId);
      const receipt = await tx.wait();

      console.log(`✅ Badge awarded:`, receipt?.hash);

      return receipt?.hash || '';
    } catch (error) {
      console.error('Badge award error:', error);
      throw new Error(`Failed to award badge: ${error}`);
    }
  }

  /**
   * Get user's badges
   */
  async getUserBadges(userAddress: string): Promise<Badge[]> {
    try {
      const badgeIds = await this.contract.getBadges(userAddress);
      const badges: Badge[] = [];

      for (const badgeId of badgeIds) {
        const metadata = await this.contract.getBadgeMetadata(badgeId);
        badges.push({
          id: badgeId.toString(),
          name: metadata.name,
          description: metadata.description,
          icon: metadata.icon,
          rarity: this.rarityFromNumber(metadata.rarity),
        });
      }

      return badges;
    } catch (error) {
      console.error('Badge fetch error:', error);
      return [];
    }
  }

  /**
   * Check if user has a specific badge
   */
  async hasBadge(userAddress: string, badgeId: number): Promise<boolean> {
    try {
      const badges = await this.getUserBadges(userAddress);
      return badges.some(b => b.id === badgeId.toString());
    } catch (error) {
      console.error('Badge check error:', error);
      return false;
    }
  }

  private rarityFromNumber(num: number): Badge['rarity'] {
    const rarities: Badge['rarity'][] = ['common', 'uncommon', 'rare', 'epic', 'legendary'];
    return rarities[num] || 'common';
  }
}

// ===== INTEGRATED MISSION SYSTEM =====
export class IntegratedMissionSystem {
  private missionTracker: MissionTracker;
  private nftManager: NFTManager;
  private badgeSystem: BadgeSystem;

  constructor(provider: ethers.Provider, signer: ethers.Signer) {
    this.missionTracker = new MissionTracker(provider, signer);
    this.nftManager = new NFTManager(provider, signer);
    this.badgeSystem = new BadgeSystem(provider, signer);
  }

  /**
   * Complete a mission with full reward chain
   */
  async completeMissionFull(
    missionId: string,
    proof: string,
    userAddress: string,
    rewardTokens: string,
    badgeId?: number
  ): Promise<{
    missionTx: string;
    rewardTx: string;
    badgeTx?: string;
  }> {
    try {
      console.log(`🚀 Starting full mission completion flow for ${missionId}`);

      // 1. Complete mission
      const { txHash: missionTx } = await this.missionTracker.completeMission(missionId, proof);

      // 2. Distribute reward tokens
      const rewardTx = await this.missionTracker.rewardUser(userAddress, missionId, rewardTokens);

      // 3. Award badge if applicable
      let badgeTx: string | undefined;
      if (badgeId) {
        badgeTx = await this.badgeSystem.awardBadge(userAddress, badgeId);
      }

      console.log(`✅ Mission completed with full rewards`);

      return {
        missionTx,
        rewardTx,
        badgeTx,
      };
    } catch (error) {
      console.error('Full mission completion error:', error);
      throw new Error(`Failed to complete mission with rewards: ${error}`);
    }
  }

  /**
   * Get all mission data for a user
   */
  async getUserMissionStatus(
    userAddress: string,
    missionIds: string[]
  ): Promise<Record<string, { completed: boolean; metadata: Mission | null }>> {
    const status: Record<string, { completed: boolean; metadata: Mission | null }> = {};

    for (const missionId of missionIds) {
      const completed = await this.missionTracker.verifyCompletion(userAddress, missionId);
      const metadata = await this.missionTracker.getMissionMetadata(missionId);

      status[missionId] = { completed, metadata };
    }

    return status;
  }

  /**
   * Get complete user profile with NFTs and badges
   */
  async getUserProfile(userAddress: string) {
    const [nftBalance, badges] = await Promise.all([
      this.nftManager.getBalance(userAddress),
      this.badgeSystem.getUserBadges(userAddress),
    ]);

    return {
      address: userAddress,
      nftBalance,
      badges,
      badgeCount: badges.length,
    };
  }
}

// Export instances
export const createMissionSystem = (provider: ethers.Provider, signer: ethers.Signer) => {
  return new IntegratedMissionSystem(provider, signer);
};

import { useState, useEffect, useCallback, useRef } from 'react';
import { Web3Auth } from '@web3auth/modal';
import { CHAIN_NAMESPACES, IProvider, WEB3AUTH_NETWORK } from '@web3auth/base';
import { ethers } from 'ethers';
import {
  EnhancedWalletManager,
  SmartWallet,
  TransactionRequest,
  GaslessQuote,
} from '../lib/wallet/EnhancedWalletManager';

// ===== TYPES =====
export interface UseEnhancedWalletState {
  // Web3Auth State
  isInitialized: boolean;
  isConnected: boolean;
  isLoading: boolean;
  user: any | null;
  userEmail: string | null;

  // Wallet State
  wallets: SmartWallet[];
  activeWallet: SmartWallet | null;
  provider: ethers.BrowserProvider | null;
  signer: ethers.Signer | null;

  // Chain State
  chainId: number | null;
  isCorrectNetwork: boolean;

  // Error State
  error: string | null;
}

export interface UseEnhancedWalletActions {
  // Auth
  login: () => Promise<void>;
  logout: () => Promise<void>;

  // Wallet Management
  createWallet: (name: string, type: 'main' | 'savings' | 'dev') => Promise<SmartWallet>;
  selectWallet: (walletId: string) => void;
  renameWallet: (walletId: string, newName: string) => Promise<void>;

  // Transactions
  sendTransaction: (to: string, value: string) => Promise<string>;
  sendGaslessTransaction: (to: string, value: string) => Promise<string>;
  checkGaslessEligibility: (walletId: string) => Promise<GaslessQuote>;

  // Recovery
  setupSocialRecovery: (walletId: string, email: string) => Promise<void>;
  setupBiometricRecovery: (walletId: string) => Promise<boolean>;
  setupGuardianRecovery: (
    walletId: string,
    primaryGuardian: string,
    backupGuardians: string[]
  ) => Promise<void>;

  // Utilities
  switchNetwork: (chainId: number) => Promise<void>;
  clearError: () => void;
}

export type UseEnhancedWalletReturn = UseEnhancedWalletState & UseEnhancedWalletActions;

// ===== CONFIGURATION =====
const SAPPHIRE_CONFIG = {
  chainNamespace: CHAIN_NAMESPACES.EIP155,
  chainId: '0x5afe', // Sapphire Mainnet (23294)
  rpcTarget: 'https://sapphire.oasis.io',
  displayName: 'Oasis Sapphire Mainnet',
  blockExplorer: 'https://explorer.oasis.io/mainnet/sapphire',
  ticker: 'ROSE',
  tickerName: 'ROSE',
};

const SUPPORTED_NETWORKS = {
  11155111: { name: 'Sepolia', rpcUrl: 'https://rpc.sepolia.org' },
  1: { name: 'Ethereum', rpcUrl: 'https://mainnet.infura.io/v3/' },
  137: { name: 'Polygon', rpcUrl: 'https://polygon-rpc.com/' },
  42161: { name: 'Arbitrum', rpcUrl: 'https://arb1.arbitrum.io/rpc' },
};

// ===== HOOK =====
export function useEnhancedWallet(web3AuthClientId: string): UseEnhancedWalletReturn {
  // State
  const [state, setState] = useState<UseEnhancedWalletState>({
    isInitialized: false,
    isConnected: false,
    isLoading: true,
    user: null,
    userEmail: null,
    wallets: [],
    activeWallet: null,
    provider: null,
    signer: null,
    chainId: null,
    isCorrectNetwork: false,
    error: null,
  });

  // Refs
  const web3authRef = useRef<Web3Auth | null>(null);
  const walletManagerRef = useRef(EnhancedWalletManager.getInstance());

  // ===== INITIALIZATION =====

  useEffect(() => {
    const initWeb3Auth = async () => {
      try {
        setState(prev => ({ ...prev, isLoading: true, error: null }));

        // Initialize Web3Auth
        const web3auth = new Web3Auth({
          clientId: web3AuthClientId,
          chainConfig: SAPPHIRE_CONFIG,
          web3AuthNetwork: WEB3AUTH_NETWORK.SAPPHIRE,
          uiConfig: {
            appName: 'MeeChain',
            theme: {
              primary: '#6A00FF',
            },
            loginGridCol: 3,
            modalZIndex: '2147483647',
          },
        });

        web3authRef.current = web3auth;
        await web3auth.initModal();

        // Check if already connected
        if (web3auth.connected) {
          await handleConnection(web3auth);
        }

        setState(prev => ({
          ...prev,
          isInitialized: true,
          isLoading: false,
        }));
      } catch (error) {
        console.error('Web3Auth initialization error:', error);
        setState(prev => ({
          ...prev,
          isInitialized: false,
          isLoading: false,
          error: 'Failed to initialize Web3Auth',
        }));
      }
    };

    initWeb3Auth();
  }, [web3AuthClientId]);

  // ===== CONNECTION HANDLER =====

  const handleConnection = async (web3auth: Web3Auth) => {
    try {
      const provider = new ethers.BrowserProvider(web3auth.provider!);
      const signer = await provider.getSigner();
      const user = await web3auth.getUserInfo();
      const { chainId } = await provider.getNetwork();

      // Initialize wallet manager
      walletManagerRef.current.setProvider(provider, signer);

      // Load or create default wallet
      const userId = user.email || (await signer.getAddress());
      let wallets = walletManagerRef.current.getWallets(userId);

      if (wallets.length === 0) {
        // Create default main wallet
        const mainWallet = await walletManagerRef.current.createSmartWallet(
          userId,
          'Main Vault',
          'main'
        );
        wallets = [mainWallet];
      }

      setState(prev => ({
        ...prev,
        isConnected: true,
        user,
        userEmail: user.email || null,
        provider,
        signer,
        wallets,
        activeWallet: wallets[0],
        chainId: Number(chainId),
        isCorrectNetwork: Number(chainId) === parseInt(SAPPHIRE_CONFIG.chainId, 16),
      }));
    } catch (error) {
      console.error('Connection error:', error);
      setState(prev => ({
        ...prev,
        error: 'Failed to connect wallet',
      }));
    }
  };

  // ===== AUTH ACTIONS =====

  const login = useCallback(async () => {
    try {
      if (!web3authRef.current) throw new Error('Web3Auth not initialized');

      setState(prev => ({ ...prev, isLoading: true, error: null }));
      await web3authRef.current.connect();
      await handleConnection(web3authRef.current);
    } catch (error) {
      console.error('Login error:', error);
      setState(prev => ({
        ...prev,
        error: error instanceof Error ? error.message : 'Login failed',
      }));
    } finally {
      setState(prev => ({ ...prev, isLoading: false }));
    }
  }, []);

  const logout = useCallback(async () => {
    try {
      if (!web3authRef.current) return;

      setState(prev => ({ ...prev, isLoading: true }));
      await web3authRef.current.logout();

      setState(prev => ({
        ...prev,
        isConnected: false,
        user: null,
        userEmail: null,
        provider: null,
        signer: null,
        wallets: [],
        activeWallet: null,
        isLoading: false,
      }));
    } catch (error) {
      console.error('Logout error:', error);
      setState(prev => ({
        ...prev,
        error: 'Logout failed',
        isLoading: false,
      }));
    }
  }, []);

  // ===== WALLET ACTIONS =====

  const createWallet = useCallback(
    async (name: string, type: 'main' | 'savings' | 'dev') => {
      try {
        if (!state.user) throw new Error('Not connected');

        const wallet = await walletManagerRef.current.createSmartWallet(
          state.user.email || state.user.sub,
          name,
          type
        );

        setState(prev => ({
          ...prev,
          wallets: [...prev.wallets, wallet],
        }));

        return wallet;
      } catch (error) {
        const message = error instanceof Error ? error.message : 'Failed to create wallet';
        setState(prev => ({ ...prev, error: message }));
        throw error;
      }
    },
    [state.user]
  );

  const selectWallet = useCallback((walletId: string) => {
    const wallet = state.wallets.find(w => w.id === walletId);
    if (!wallet) {
      setState(prev => ({ ...prev, error: 'Wallet not found' }));
      return;
    }

    setState(prev => ({
      ...prev,
      activeWallet: wallet,
      error: null,
    }));
  }, [state.wallets]);

  const renameWallet = useCallback(
    async (walletId: string, newName: string) => {
      try {
        walletManagerRef.current.updateWallet(walletId, { name: newName });

        setState(prev => ({
          ...prev,
          wallets: prev.wallets.map(w =>
            w.id === walletId ? { ...w, name: newName } : w
          ),
        }));
      } catch (error) {
        const message = error instanceof Error ? error.message : 'Failed to rename wallet';
        setState(prev => ({ ...prev, error: message }));
        throw error;
      }
    },
    []
  );

  // ===== TRANSACTION ACTIONS =====

  const sendTransaction = useCallback(
    async (to: string, value: string) => {
      try {
        if (!state.activeWallet) throw new Error('No active wallet');

        const txRequest: TransactionRequest = {
          to: to as `0x${string}`,
          value,
        };

        const txHash = await walletManagerRef.current.sendTransaction(
          state.activeWallet.id,
          txRequest,
          false
        );

        return txHash;
      } catch (error) {
        const message = error instanceof Error ? error.message : 'Transaction failed';
        setState(prev => ({ ...prev, error: message }));
        throw error;
      }
    },
    [state.activeWallet]
  );

  const sendGaslessTransaction = useCallback(
    async (to: string, value: string) => {
      try {
        if (!state.activeWallet) throw new Error('No active wallet');

        // Check gasless eligibility first
        const quote = await walletManagerRef.current.checkGaslessEligibility(
          state.activeWallet.address
        );

        if (!quote.eligible) {
          throw new Error(quote.reason || 'Not eligible for gasless');
        }

        const txRequest: TransactionRequest = {
          to: to as `0x${string}`,
          value,
        };

        const txHash = await walletManagerRef.current.sendTransaction(
          state.activeWallet.id,
          txRequest,
          true
        );

        return txHash;
      } catch (error) {
        const message = error instanceof Error ? error.message : 'Gasless transaction failed';
        setState(prev => ({ ...prev, error: message }));
        throw error;
      }
    },
    [state.activeWallet]
  );

  const checkGaslessEligibility = useCallback(
    async (walletId: string) => {
      try {
        const wallet = state.wallets.find(w => w.id === walletId);
        if (!wallet) throw new Error('Wallet not found');

        return await walletManagerRef.current.checkGaslessEligibility(wallet.address);
      } catch (error) {
        const message = error instanceof Error ? error.message : 'Failed to check eligibility';
        setState(prev => ({ ...prev, error: message }));
        throw error;
      }
    },
    [state.wallets]
  );

  // ===== RECOVERY ACTIONS =====

  const setupSocialRecovery = useCallback(
    async (walletId: string, email: string) => {
      try {
        await walletManagerRef.current.setupSocialRecovery(walletId, email);
        setState(prev => ({
          ...prev,
          wallets: prev.wallets.map(w =>
            w.id === walletId && w.recoveryConfig
              ? {
                  ...w,
                  recoveryConfig: {
                    ...w.recoveryConfig,
                    method: 'social',
                    socialRecoveryEmail: email,
                  },
                }
              : w
          ),
        }));
      } catch (error) {
        const message = error instanceof Error ? error.message : 'Social recovery setup failed';
        setState(prev => ({ ...prev, error: message }));
        throw error;
      }
    },
    []
  );

  const setupBiometricRecovery = useCallback(
    async (walletId: string) => {
      try {
        const success = await walletManagerRef.current.setupBiometricRecovery(walletId);
        if (success) {
          setState(prev => ({
            ...prev,
            wallets: prev.wallets.map(w =>
              w.id === walletId && w.recoveryConfig
                ? {
                    ...w,
                    recoveryConfig: {
                      ...w.recoveryConfig,
                      biometricEnabled: true,
                    },
                  }
                : w
            ),
          }));
        }
        return success;
      } catch (error) {
        const message = error instanceof Error ? error.message : 'Biometric setup failed';
        setState(prev => ({ ...prev, error: message }));
        throw error;
      }
    },
    []
  );

  const setupGuardianRecovery = useCallback(
    async (walletId: string, primaryGuardian: string, backupGuardians: string[]) => {
      try {
        await walletManagerRef.current.setupGuardianRecovery(
          walletId,
          primaryGuardian,
          backupGuardians
        );
        setState(prev => ({
          ...prev,
          wallets: prev.wallets.map(w =>
            w.id === walletId && w.recoveryConfig
              ? {
                  ...w,
                  recoveryConfig: {
                    ...w.recoveryConfig,
                    method: 'guardian',
                    primaryGuardian,
                    backupGuardians,
                  },
                }
              : w
          ),
        }));
      } catch (error) {
        const message = error instanceof Error ? error.message : 'Guardian setup failed';
        setState(prev => ({ ...prev, error: message }));
        throw error;
      }
    },
    []
  );

  // ===== UTILITY ACTIONS =====

  const switchNetwork = useCallback(async (newChainId: number) => {
    try {
      if (!web3authRef.current?.provider) throw new Error('Provider not available');

      const network = SUPPORTED_NETWORKS[newChainId as keyof typeof SUPPORTED_NETWORKS];
      if (!network) throw new Error('Network not supported');

      await (web3authRef.current.provider as any).request({
        method: 'wallet_switchEthereumChain',
        params: [{ chainId: `0x${newChainId.toString(16)}` }],
      });

      setState(prev => ({
        ...prev,
        chainId: newChainId,
        isCorrectNetwork: newChainId === 23294, // Sapphire
      }));
    } catch (error) {
      const message = error instanceof Error ? error.message : 'Network switch failed';
      setState(prev => ({ ...prev, error: message }));
      throw error;
    }
  }, []);

  const clearError = useCallback(() => {
    setState(prev => ({ ...prev, error: null }));
  }, []);

  // ===== RETURN =====

  return {
    ...state,
    login,
    logout,
    createWallet,
    selectWallet,
    renameWallet,
    sendTransaction,
    sendGaslessTransaction,
    checkGaslessEligibility,
    setupSocialRecovery,
    setupBiometricRecovery,
    setupGuardianRecovery,
    switchNetwork,
    clearError,
  };
}

import React, { useState } from 'react';
import { useEnhancedWallet } from '../hooks/useEnhancedWallet';
import { 
  ArrowRightIcon,
  ArrowLeftIcon,
  WalletIcon,
  PlusIcon,
  InboxIcon,
  ShieldCheckIcon,
  BoltIcon,
  FingerPrintIcon,
  UserGroupIcon,
  DocumentDuplicateIcon,
  CheckIcon,
  ArrowRightOnRectangleIcon,
  ArrowLeftOnRectangleIcon
} from '@heroicons/react/24/outline';

interface EnhancedWalletUIProps {
  web3AuthClientId: string;
  onMintSuccess?: (txHash: string) => void;
  onMissionComplete?: (missionId: string, walletAddress: string) => void;
}

export const EnhancedWalletUI: React.FC<EnhancedWalletUIProps> = ({
  web3AuthClientId,
  onMintSuccess,
  onMissionComplete,
}) => {
  const wallet = useEnhancedWallet(web3AuthClientId);
  const [activeTab, setActiveTab] = useState<'wallets' | 'send' | 'recovery' | 'missions'>('wallets');
  const [showCreateWallet, setShowCreateWallet] = useState(false);
  const [newWalletName, setNewWalletName] = useState('');
  const [walletType, setWalletType] = useState<'main' | 'savings' | 'dev'>('main');
  const [sendTo, setSendTo] = useState('');
  const [sendAmount, setSendAmount] = useState('');
  const [copiedAddress, setCopiedAddress] = useState<string | null>(null);
  const [isGasless, setIsGasless] = useState(false);
  const [gaslessQuote, setGaslessQuote] = useState<any>(null);

  // ===== HANDLERS =====

  const handleCreateWallet = async () => {
    try {
      await wallet.createWallet(newWalletName || `Wallet ${wallet.wallets.length + 1}`, walletType);
      setNewWalletName('');
      setShowCreateWallet(false);
    } catch (error) {
      console.error('Create wallet error:', error);
    }
  };

  const handleSendTransaction = async () => {
    try {
      if (!sendTo || !sendAmount) {
        wallet.clearError();
        return;
      }

      const txHash = isGasless
        ? await wallet.sendGaslessTransaction(sendTo, sendAmount)
        : await wallet.sendTransaction(sendTo, sendAmount);

      onMintSuccess?.(txHash);
      setSendTo('');
      setSendAmount('');
      alert(`✅ Transaction sent: ${txHash}`);
    } catch (error) {
      console.error('Send error:', error);
    }
  };

  const handleCheckGasless = async () => {
    try {
      if (!wallet.activeWallet) return;
      const quote = await wallet.checkGaslessEligibility(wallet.activeWallet.id);
      setGaslessQuote(quote);
    } catch (error) {
      console.error('Gasless check error:', error);
    }
  };

  const handleSetupSocialRecovery = async (email: string) => {
    try {
      if (!wallet.activeWallet) return;
      await wallet.setupSocialRecovery(wallet.activeWallet.id, email);
      alert('✅ Social recovery configured');
    } catch (error) {
      console.error('Social recovery error:', error);
    }
  };

  const handleSetupBiometric = async () => {
    try {
      if (!wallet.activeWallet) return;
      const success = await wallet.setupBiometricRecovery(wallet.activeWallet.id);
      if (success) {
        alert('✅ Biometric recovery enabled');
      } else {
        alert('❌ Biometric not supported on this device');
      }
    } catch (error) {
      console.error('Biometric error:', error);
    }
  };

  const copyAddress = (address: string) => {
    navigator.clipboard.writeText(address);
    setCopiedAddress(address);
    setTimeout(() => setCopiedAddress(null), 2000);
  };

  const truncateAddress = (address: string) => {
    return `${address.slice(0, 6)}...${address.slice(-4)}`;
  };

  // ===== RENDER =====

  if (!wallet.isInitialized) {
    return (
      <div className="flex items-center justify-center h-64 bg-slate-900/50 rounded-lg">
        <div className="text-center">
          <div className="animate-spin mb-4">
            <WalletIcon className="w-8 h-8 text-sky-500 mx-auto" />
          </div>
          <p className="text-slate-400">Initializing wallet...</p>
        </div>
      </div>
    );
  }

  if (!wallet.isConnected) {
    return (
      <div className="bg-slate-800 border border-slate-700 rounded-xl shadow-lg p-8 text-center">
        <WalletIcon className="w-16 h-16 mx-auto mb-4 text-sky-500" />
        <h2 className="text-2xl font-bold text-slate-100 mb-2">MeeChain Wallet</h2>
        <p className="text-slate-400 mb-6">
          Secure, modular wallet with Account Abstraction support
        </p>
        <button
          onClick={wallet.login}
          disabled={wallet.isLoading}
          className="bg-sky-600 hover:bg-sky-500 disabled:bg-slate-600 text-white px-8 py-3 rounded-lg font-semibold flex items-center gap-2 mx-auto transition-colors"
        >
          <ArrowRightOnRectangleIcon className="w-5 h-5" />
          {wallet.isLoading ? 'Connecting...' : 'Connect Wallet'}
